def format_bytes(n):
    units = ['B', 'KB', 'MB', 'GB', 'TB', 'PB']
    i = 0
    while n >= 1024 and i < len(units) - 1:
        n /= 1024.0
        i += 1
    # Format to 1 or 2 decimal places depending on the unit
    if i == 0:
        return f"{int(n)} {units[i]}"
    elif i == 1:
        return f"{n:.1f} {units[i]}"
    else:
        return f"{n:.2f} {units[i]}"'
